/// The signature badge (spec §9.1).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum SignatureKind {
    Verified,
    Unverified,
    Bad,
    Expired,
    UnknownKey,
    Unsigned,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SignaturePayload {
    pub kind: SignatureKind,
    pub signer: String,
    pub key: String,
    pub fingerprint: String,
    /// GPG trust level (`fully`, `ultimate`, …); empty when git has none.
    pub trust: String,
    pub detail: Option<String>,
}

impl GraphPayload {
    /// ASCII dump: layout grid, then the row summary (WIP rows show their worktree).
    pub fn ascii(&self) -> String {
        let segs: Vec<Vec<Segment>> = self.rows.iter().map(|r| r.segments.iter().map(|&s| Segment::unpack(s)).collect()).collect();
        let labels: Vec<String> = self
            .rows
            .iter()
            .map(|r| match &r.wip {
                Some(w) => format!("// WIP {}", w.worktree_name.as_deref().unwrap_or("(main)")),
                None => r.summary.clone(),
            })
            .collect();
        let rows: Vec<AsciiRow> = self
            .rows
            .iter()
            .zip(&segs)
            .zip(&labels)
            .map(|((r, s), l)| AsciiRow { lane: r.lane, kind: r.kind, segments: s, label: l })
            .collect();
        render_ascii(&rows, self.max_lanes)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "lowercase")]
#[ts(export)]
pub enum Eol {
    Lf,
    Crlf,
    Mixed,
    None,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct BlobPayload {
    #[ts(type = "number")]
    pub size: u64,
    pub binary: bool,
    /// e.g. `UTF-8`, `UTF-8 BOM`, `UTF-16LE`, `ISO-8859-1`; empty for binary or unloaded sides.
    pub encoding: String,
    pub eol: Eol,
    /// Decoded text; `None` for binary files and for sides held back by the large-file prompt.
    pub text: Option<String>,
    /// Raw bytes, base64, for binary images only (spec §10.4).
    pub base64: Option<String>,
    /// The loaded bytes' `worktree_id` (2B Deviation 12): the save base of a working-tree side.
    /// `None` when the side wasn't loaded (too large).
    pub hash: Option<String>,
    /// A working-tree side whose `text` is its clean form, as git compares it, and that form
    /// differs from the file by more than line endings (a `filter` driver, `ident`): the text
    /// isn't the file's, so it's read-only. Absent otherwise.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    #[ts(optional, as = "Option<bool>")]
    pub filtered: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DiffContentsPayload {
    pub old: Option<BlobPayload>,
    pub new: Option<BlobPayload>,
    /// A side is over 2 MiB and `force` was false: show "Large file — load anyway?". Even with
    /// `force`, a side over 64 MiB (`MAX_FORCED_BYTES`) stays `too_large`: that size is never loaded.
    pub too_large: bool,
    /// Only the line endings changed (spec §10.2 banner).
    pub eol_only: bool,
    /// The path has a raster-image extension (the UI shows the image diff).
    pub image: bool,
}

/// One side of a binary file as a hex dump (`hexDump`): `hexdump -C` lines of its first
/// `shown` bytes, at most `HexDumpPayload::cap`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct HexSide {
    /// The whole side's size in bytes.
    #[ts(type = "number")]
    pub size: u64,
    /// How many bytes `dump` covers: `size`, or the cap when the side is larger.
    #[ts(type = "number")]
    pub shown: u64,
    pub dump: String,
}

/// Both sides of a binary file as hex dumps, for File View and the hex diff. `None`: no such side
/// (an added or deleted file).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct HexDumpPayload {
    pub old: Option<HexSide>,
    pub new: Option<HexSide>,
    /// The most bytes dumped per side.
    #[ts(type = "number")]
    pub cap: u64,
}
